const fs = require('fs');
const statePath = '/tmp/memebot_position.json';
let position = null;
try {
  if (fs.existsSync(statePath)) {
    position = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  }
} catch (e) {}

if (!position || !position.tokenAddress) {
  return [{ json: { hasPosition: false } }];
}
return [{ json: { hasPosition: true, ...position } }];

const fs = require('fs');
const root = $json.body || $json;
const pairs = Array.isArray(root.pairs) ? root.pairs : [];
const position = $item(0).$node['Load Open Position'].json;
const pair = pairs
  .filter(pair => String(pair.chainId || '').toLowerCase() === 'solana')
  .sort((a, b) => Number(b.liquidity?.usd || 0) - Number(a.liquidity?.usd || 0))[0] || null;

if (!pair) {
  return [{ json: { ...position, shouldExit: 0, reason: 'NO_PRICE_DATA' } }];
}

const entryPrice = Number(position.entryPrice || 0);
const currentPrice = Number(pair.priceUsd || 0);
const now = Date.now();
const maxHoldMs = 90 * 60 * 1000;
const elapsed = now - Number(position.entryTime || now);

if (!(entryPrice > 0) || !(currentPrice > 0)) {
  return [{ json: { ...position, entryPrice, exitPrice: currentPrice, shouldExit: 0, reason: 'INVALID_PRICE_DATA' } }];
}

const pnlPct = ((currentPrice - entryPrice) / entryPrice) * 100;
const peakPrice = Math.max(Number(position.peakPrice || entryPrice), currentPrice);
const peakPnlPct = ((peakPrice - entryPrice) / entryPrice) * 100;
const currentLiquidity = Number(pair.liquidity?.usd || 0);
const entryLiquidity = Number(position.liquidity || 0);
const marketCap = Number(pair.marketCap || pair.fdv || 0);

const elapsedMin = Math.max(elapsed / 60000, 0.25);
const velocityPctPerMin = pnlPct / elapsedMin;

let shouldExit = 0;
let reason = 'HOLD';

// EXIT RULES v6 — tighter SL, faster velocity kill, better trailing
// GRACE (first 5 min): SL -8% — if it dumps this fast, token is dead
// NORMAL (5-15 min): SL -6%
// LATE (15+ min): SL -4%
// VELOCITY KILL: dumping > 2%/min with loss > -3% => instant exit

const gracePeriodMs = 5 * 60 * 1000;
const normalPeriodMs = 15 * 60 * 1000;
const isInGracePeriod = elapsed < gracePeriodMs;
const isLateMode = elapsed > normalPeriodMs;

// 0. VELOCITY KILL — faster trigger
if (velocityPctPerMin <= -2 && pnlPct < -3) {
  shouldExit = 1;
  reason = 'VELOCITY_KILL';
}

// 0b. INSTANT DUMP — price never went green and already -5% in under 2 min
if (!shouldExit && elapsed < (2 * 60 * 1000) && peakPnlPct < 1 && pnlPct <= -5) {
  shouldExit = 1;
  reason = 'INSTANT_DUMP';
}

// 1. Dynamic stop loss based on time phase
if (!shouldExit) {
  const slMultiplier = isInGracePeriod ? 0.92 : (isLateMode ? 0.96 : 0.94);
  if (currentPrice <= entryPrice * slMultiplier) {
    shouldExit = 1;
    reason = isInGracePeriod ? 'STOPLOSS8P_EARLY' : (isLateMode ? 'STOPLOSS4P_LATE' : 'STOPLOSS6P');
  }
}

// 2. Trailing stop: activate at +8%, trail 5% from peak
if (!shouldExit && peakPnlPct >= 8 && currentPrice <= peakPrice * 0.95) {
  shouldExit = 1;
  reason = 'TRAILINGSTOP';
}

// 3. Take profit at +20%
if (!shouldExit && currentPrice >= entryPrice * 1.20) {
  shouldExit = 1;
  reason = 'TAKEPROFIT20P';
}

// 4. Protect breakeven: was up +4%, now back to -0.5%
if (!shouldExit && peakPnlPct >= 4 && pnlPct <= -0.5) {
  shouldExit = 1;
  reason = 'BREAKEVENEXIT';
}

// 5. Protect green: was up +6%, now below +1.5%
if (!shouldExit && peakPnlPct >= 6 && pnlPct <= 1.5) {
  shouldExit = 1;
  reason = 'PROTECTGREEN';
}

// 6. Liquidity drain: exit if liq drops 30% from entry
if (!shouldExit && entryLiquidity > 0 && currentLiquidity > 0 && currentLiquidity < entryLiquidity * 0.70) {
  shouldExit = 1;
  reason = 'LIQUIDITY_DRAIN';
}

// 7. No momentum after 20min — gives token more time
if (!shouldExit && !isInGracePeriod && elapsed > (20 * 60 * 1000) && pnlPct < 2 && pnlPct > -3) {
  shouldExit = 1;
  reason = 'STALE_NO_MOMENTUM';
}

// 8. Force exit after 90min
if (!shouldExit && elapsed > maxHoldMs) {
  shouldExit = 1;
  reason = 'FORCE_EXIT_90M';
}

const statePath = '/tmp/memebot_position.json';
try {
  const posData = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  posData.peakPrice = peakPrice;
  fs.writeFileSync(statePath, JSON.stringify(posData, null, 2), 'utf8');
} catch (e) {}

const solAmountLamports = Number(position.solAmountLamports || position.amount || 0);
const profitLamports = Math.floor(solAmountLamports * (pnlPct / 100));

return [{
  json: {
    ...position,
    entryPrice,
    exitPrice: currentPrice,
    peakPrice,
    marketCap,
    liquidity: currentLiquidity,
    profitLamports,
    profit: profitLamports / 1e9,
    profitSOL: profitLamports / 1e9,
    pnlPct,
    peakPnlPct,
    velocityPctPerMin: Number(velocityPctPerMin.toFixed(3)),
    isInGracePeriod,
    isLateMode,
    elapsedMinutes: Math.floor(elapsed / 60000),
    reason,
    shouldExit
  }
}];

const fs = require('fs');
const statePath = '/tmp/memebot_position.json';
try {
  if (fs.existsSync(statePath)) fs.unlinkSync(statePath);
} catch (e) {}
return [{ json: { ok: true, message: 'POSITION_CLEARED_AFTER_EXIT' } }];

const exit = $item(0).$node['Evaluate Exit Rules'].json;
const quoteNode = $item(0).$node['Jupiter Quote Sell'].json;
const quote = quoteNode.body || quoteNode || {};
const outLamports = Number(quote.outAmount || 0);
const inLamports = Number(exit.solAmountLamports || exit.amount || 0);

// In dry-run, always use the price-based PnL from Evaluate Exit Rules.
// The Jupiter quote can differ from the Dexscreener price due to slippage
// or timing, which would flip the sign and corrupt the trade log.
// (e.g. a TAKE_PROFIT trade showing a negative PnL)
const priceBasedProfitLamports = Number(exit.profitLamports || 0);

// For live mode: use real on-chain amounts (outLamports - inLamports).
// For dry-run: use the price-based estimate which matches the exit reason.
const profitLamports = priceBasedProfitLamports;

return [{
  json: {
    ...exit,
    sellTxid: 'DRY_RUN_SELL_' + Date.now(),
    profitLamports,
    profit: profitLamports / 1e9,
    isDryRun: true
  }
}];

const fs = require('fs');
const exit = $item(0).$node['Evaluate Exit Rules'].json;
const profitLamports = Number(exit.profitLamports || 0);

return [{
  json: {
    ...exit,
    sellTxid: 'SELL_FAILED_FORCE_EXIT_' + Date.now(),
    profitLamports: Math.min(profitLamports, -Number(exit.solAmountLamports || 700000000)),
    profit: Math.min(profitLamports, -Number(exit.solAmountLamports || 700000000)) / 1e9,
    reason: exit.reason + '_SELL_FAILED',
    isDryRun: true
  }
}];
